function(container, apiUrl, tables) {
  let currentForecastData = [];

  // 店舗データを読み込んでセレクトボックスに設定
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 予測結果テーブルの描画
  function renderForecastTable(results) {
    const tbody = container.querySelector('#forecast-table-body');
    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.予測結果ID}">
        <td>${result.商品コード || '-'}</td>
        <td>${result.商品名 || '-'}</td>
        <td>${result.予測対象日 ? new Date(result.予測対象日).toLocaleDateString() : '-'}</td>
        <td>${result.予測数量 || 0}</td>
        <td>${result.予測精度 || 0}%</td>
        <td>${result.推奨発注数量 || 0}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${result.予測結果ID}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // グラフ描画関数
  function drawForecastChart(data) {
    const canvas = container.querySelector('#forecast-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) return;

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // データの最大値・最小値を計算
    const maxValue = Math.max(...data.map(d => Math.max(d.予測数量 || 0, d.実績数量 || 0)));
    const minValue = 0;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, padding + chartHeight);
    ctx.lineTo(padding + chartWidth, padding + chartHeight);
    ctx.stroke();

    // データポイントの描画
    if (data.length > 1) {
      const stepX = chartWidth / (data.length - 1);

      // 予測値の線
      ctx.strokeStyle = '#4a90e2';
      ctx.lineWidth = 2;
      ctx.beginPath();
      data.forEach((point, index) => {
        const x = padding + index * stepX;
        const y = padding + chartHeight - ((point.予測数量 || 0) / maxValue) * chartHeight;
        if (index === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();

      // 実績値の線（データがある場合）
      ctx.strokeStyle = '#ff6a00';
      ctx.lineWidth = 2;
      ctx.beginPath();
      let hasActual = false;
      data.forEach((point, index) => {
        if (point.実績数量 !== null && point.実績数量 !== undefined) {
          const x = padding + index * stepX;
          const y = padding + chartHeight - (point.実績数量 / maxValue) * chartHeight;
          if (!hasActual) {
            ctx.moveTo(x, y);
            hasActual = true;
          } else {
            ctx.lineTo(x, y);
          }
        }
      });
      if (hasActual) ctx.stroke();
    }

    // 凡例
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '12px sans-serif';
    ctx.fillText('予測値', padding + 10, 20);
    ctx.fillStyle = '#4a90e2';
    ctx.fillRect(padding + 60, 12, 20, 3);

    ctx.fillStyle = '#d0e4ff';
    ctx.fillText('実績値', padding + 100, 20);
    ctx.fillStyle = '#ff6a00';
    ctx.fillRect(padding + 150, 12, 20, 3);
  }

  // 比較チャート描画
  function drawComparisonChart(data) {
    const canvas = container.querySelector('#comparison-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) return;

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, padding + chartHeight);
    ctx.lineTo(padding + chartWidth, padding + chartHeight);
    ctx.stroke();

    // 棒グラフの描画
    const barWidth = chartWidth / data.length * 0.8;
    const maxValue = Math.max(...data.map(d => Math.max(d.予測数量 || 0, d.実績数量 || 0)));

    data.forEach((point, index) => {
      const x = padding + (index * chartWidth / data.length);

      // 予測値の棒
      if (point.予測数量) {
        const height = (point.予測数量 / maxValue) * chartHeight;
        ctx.fillStyle = '#4a90e2';
        ctx.fillRect(x, padding + chartHeight - height, barWidth / 2, height);
      }

      // 実績値の棒
      if (point.実績数量) {
        const height = (point.実績数量 / maxValue) * chartHeight;
        ctx.fillStyle = '#ff6a00';
        ctx.fillRect(x + barWidth / 2, padding + chartHeight - height, barWidth / 2, height);
      }
    });
  }

  // 予測精度指標の更新
  function updateMetrics(data) {
    if (!data || data.length === 0) return;

    // 予測精度の平均を計算
    const validData = data.filter(d => d.予測精度 !== null && d.予測精度 !== undefined);
    const avgAccuracy = validData.length > 0 ? 
      (validData.reduce((sum, d) => sum + (d.予測精度 || 0), 0) / validData.length).toFixed(1) : '-';

    container.querySelector('#accuracy-value').textContent = avgAccuracy + '%';
    container.querySelector('#mae-value').textContent = '計算中...';
    container.querySelector('#r2-value').textContent = '計算中...';
  }

  // 影響要因分析の表示
  function updateFactorAnalysis() {
    const factorContainer = container.querySelector('#factor-analysis');
    const factors = [
      { name: '季節性', impact: '高', value: '85%' },
      { name: '天候', impact: '中', value: '62%' },
      { name: 'イベント', impact: '中', value: '58%' },
      { name: '曜日', impact: '低', value: '34%' }
    ];

    factorContainer.innerHTML = factors.map(factor => `
      <div class="factor-item">
        <span>${factor.name}</span>
        <span class="metric-value">${factor.value}</span>
      </div>
    `).join('');
  }

  // 天候・イベント情報の表示
  function updateWeatherAndEventInfo() {
    const weatherInfo = container.querySelector('#weather-info');
    const eventInfo = container.querySelector('#event-info');

    weatherInfo.innerHTML = `
      <p><strong>今日:</strong> 晴れ 最高気温: 25℃</p>
      <p><strong>明日:</strong> 曇り 最高気温: 23℃</p>
      <p><strong>週末:</strong> 雨の予報 最高気温: 20℃</p>
    `;

    eventInfo.innerHTML = `
      <p><strong>今週末:</strong> 地域祭り (来場者予想: 5,000人)</p>
      <p><strong>来週:</strong> 特売セール実施予定</p>
    `;
  }

  // バリデーション関数
  function validateForecastConditions() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const model = container.querySelector('#model-select').value;

    const errors = [];

    if (!storeId) errors.push('店舗を選択してください');
    if (!category) errors.push('商品カテゴリを選択してください');
    if (!startDate) errors.push('予測期間の開始日を設定してください');
    if (!endDate) errors.push('予測期間の終了日を設定してください');
    if (!model) errors.push('予測モデルを選択してください');

    if (startDate && endDate && new Date(startDate) >= new Date(endDate)) {
      errors.push('開始日は終了日より前の日付を入力してください');
    }

    if (startDate && new Date(startDate) < new Date()) {
      errors.push('開始日は現在日以降の日付を設定してください');
    }

    return errors;
  }

  // エラーメッセージ表示
  function showError(messages) {
    const errorDiv = container.querySelector('#error-message');
    if (messages.length > 0) {
      errorDiv.innerHTML = messages.map(msg => `<p>${msg}</p>`).join('');
      errorDiv.classList.remove('hidden');
    } else {
      errorDiv.classList.add('hidden');
    }
  }

  // CSV エクスポート
  function exportForecastResults() {
    if (currentForecastData.length === 0) {
      alert('エクスポートする予測結果がありません');
      return;
    }

    const headers = ['商品コード', '商品名', '予測対象日', '予測数量', '予測精度', '推奨発注数量'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentForecastData.map(row => [
        row.商品コード || '',
        row.商品名 || '',
        row.予測対象日 ? new Date(row.予測対象日).toLocaleDateString() : '',
        row.予測数量 || 0,
        (row.予測精度 || 0) + '%',
        row.推奨発注数量 || 0
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `需要予測結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  loadStores();

  // 今日の日付を開始日のデフォルトに設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#start-date').value = today;

  // 1週間後を終了日のデフォルトに設定
  const nextWeek = new Date();
  nextWeek.setDate(nextWeek.getDate() + 7);
  container.querySelector('#end-date').value = nextWeek.toISOString().split('T')[0];

  // イベントリスナー
  container.querySelector('#btn-execute-forecast').addEventListener('click', async () => {
    const errors = validateForecastConditions();
    if (errors.length > 0) {
      showError(errors);
      return;
    }

    showError([]);

    // 処理中表示
    container.querySelector('#forecast-processing').classList.remove('hidden');
    container.querySelector('#forecast-results').classList.add('hidden');

    try {
      // 模擬的な予測処理（実際はAPIを呼び出し）
      await new Promise(resolve => setTimeout(resolve, 2000));

      // 模擬データで結果表示
      const mockResults = [
        {
          予測結果ID: '1',
          商品コード: 'P001',
          商品名: 'おにぎり（鮭）',
          予測対象日: new Date().toISOString(),
          予測数量: 45,
          予測精度: 87,
          推奨発注数量: 50,
          実績数量: 42
        },
        {
          予測結果ID: '2',
          商品コード: 'P002',
          商品名: 'サンドイッチ',
          予測対象日: new Date().toISOString(),
          予測数量: 32,
          予測精度: 82,
          推奨発注数量: 35,
          実績数量: 30
        }
      ];

      currentForecastData = mockResults;

      // 結果表示
      container.querySelector('#forecast-processing').classList.add('hidden');
      container.querySelector('#forecast-results').classList.remove('hidden');

      renderForecastTable(mockResults);
      drawForecastChart(mockResults);
      drawComparisonChart(mockResults);
      updateMetrics(mockResults);
      updateFactorAnalysis();
      updateWeatherAndEventInfo();

    } catch (error) {
      showError(['予測処理中にエラーが発生しました: ' + error.message]);
      container.querySelector('#forecast-processing').classList.add('hidden');
    }
  });

  container.querySelector('#btn-clear-conditions').addEventListener('click', () => {
    container.querySelector('#store-select').value = '';
    container.querySelector('#category-select').value = '';
    container.querySelector('#start-date').value = today;
    container.querySelector('#end-date').value = nextWeek.toISOString().split('T')[0];
    container.querySelector('#model-select').value = '';
    container.querySelector('#seasonal-factor').checked = false;
    container.querySelector('#event-factor').checked = false;
    container.querySelector('#weather-factor').checked = false;
    showError([]);
  });

  container.querySelector('#btn-export-forecast').addEventListener('click', exportForecastResults);

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      window.showScreen('scr-1778591885672'); // AI需要予測処理画面へ遷移
    }
  });
}
